package com.agritech.service;import com.agritech.model.MandiPrice;import java.util.List;public interface MandiService{List<MandiPrice>findPrices(String crop,String state,String district);default MandiPrice bestPrice(String c,String s,String d){return findPrices(c,s,d).stream().findFirst().orElseThrow(()->new IllegalArgumentException("No genuine mandi record is currently available for "+c+"."));}}
